namespace {
void require(bool okay,const char* message){if(!okay)throw std::runtime_error(message);}
void exposeHome(MainWindow& window,QWidget* control){
 require(control,"requested Home control exists");auto* ribbon=window.findChild<QTabWidget*>("workspace.ribbon");for(int i=0;i<ribbon->count();++i)if(ribbon->tabText(i)=="Home")ribbon->setCurrentIndex(i);
 require(window.executeCommand("view.ribbon.open"),"open the actual Home command row");QApplication::processEvents();auto* page=dynamic_cast<RibbonPage*>(ribbon->currentWidget());require(page,"Home uses the responsive page");page->ensureWidgetVisible(control,4,0);QApplication::processEvents();
}
int blackInk(const QImage& image,const QRect& box){int pixels=0;for(int y=box.top();y<=box.bottom();++y)for(int x=box.left();x<=box.right();++x){const auto color=image.pixelColor(x,y);if(color.red()<80&&color.green()<80&&color.blue()<80)++pixels;}return pixels;}
QRect inkBounds(const QImage& image,const QRect& box){QRect bounds;for(int y=box.top();y<=box.bottom();++y)for(int x=box.left();x<=box.right();++x){const auto color=image.pixelColor(x,y);if(std::max({color.red(),color.green(),color.blue()})<110)bounds=bounds.isNull()?QRect(x,y,1,1):bounds.united(QRect(x,y,1,1));}return bounds;}
struct Fixture {
 MainWindow window;
 WorksheetView* view;
 WorksheetModel* model;
 Fixture(){window.resize(1280,720);window.move(0,0);window.show();window.activateWindow();QApplication::processEvents();view=window.findChild<WorksheetView*>("worksheet.grid");require(view,"native worksheet exists");model=dynamic_cast<WorksheetModel*>(view->model());const auto sheet=model->sheetId().toStdString();for(int col=2;col<=4;++col)require(model->apply(Json::array({{{"type","set_cell"},{"sheet",sheet},{"row",7},{"col",col+1},{"input",std::to_string(0.14+col*.01)},{"style",{{"numberFormat","0%"},{"fontSize",12}}}}})),"seed black driver values");view->setCurrentIndex(model->index(6,2));view->selectionModel()->select(QItemSelection(model->index(6,2),model->index(6,4)),QItemSelectionModel::ClearAndSelect);require(window.executeCommand("view.ribbon"),"collapse source ribbon");view->setFocus();QApplication::processEvents();}
 QWidget* open(bool font){view->setFocus();QTest::keyClick(view,font?Qt::Key_1:Qt::Key_6,Qt::AltModifier);QApplication::processEvents();auto* palette=window.findChild<QWidget*>(font?"tutorial.fontPalette":"tutorial.fillPalette");require(palette&&palette->isVisible()&&QApplication::activePopupWidget()==palette,"real Alt shortcut opens native palette");return palette;}
};
void initialAutomatic(){
 Fixture f;const auto before=f.window.currentSession().snapshot();const auto selected=f.view->selectionModel()->selection();const auto viewport=f.view->viewport()->mapTo(&f.window,QPoint());const auto horizontal=f.view->horizontalScrollBar()->value(),vertical=f.view->verticalScrollBar()->value();const auto text=f.view->visualRect(f.model->index(6,3)).adjusted(5,4,-5,-4);const auto original=f.view->viewport()->grab().toImage();const auto ink=blackInk(original,text);require(ink>10,"fixture renders black percentage text before opening");QPointer<QWidget> palette=f.open(true);const auto opened=f.view->viewport()->grab().toImage();std::cerr<<"Black driver ink before="<<ink<<" palette="<<blackInk(opened,text)<<'\n';require(blackInk(opened,text)>=ink*.9,"opening Font Color preserves rendered black driver values instead of previewing white");auto* automatic=palette->findChild<QToolButton*>("tutorial.font.automatic");require(automatic&&automatic->hasFocus(),"initial Font Color keyboard focus is the observed Automatic row");require(f.window.currentSession().snapshot()==before&&f.view->selectionModel()->selection()==selected,"opening Automatic preserves content, styles, selection and history");QTest::keyClick(automatic,Qt::Key_Escape);QApplication::processEvents();require((!palette||!palette->isVisible())&&blackInk(f.view->viewport()->grab().toImage(),text)==ink&&f.window.currentSession().snapshot()==before,"Escape restores original rendering without a formatting transaction");require(f.view->viewport()->mapTo(&f.window,QPoint())==viewport&&f.view->horizontalScrollBar()->value()==horizontal&&f.view->verticalScrollBar()->value()==vertical,"palette opening and cancellation preserve viewport and scroll");
}
void sourceLayout(){
 for(int variant=0;variant<3;++variant){const bool font=variant!=0,recent=variant==2;Fixture f;if(recent)f.window.setProperty("tutorial.recentFontColors",QStringList{"#0000ff"});const auto before=f.window.currentSession().snapshot();const auto selected=f.view->selectionModel()->selection();QPointer<QWidget> palette=f.open(font);const auto position=f.window.mapFromGlobal(palette->mapToGlobal(QPoint()));std::cerr<<(font?"Font":"Fill")<<" popup "<<position.x()<<','<<position.y()<<' '<<palette->width()<<'x'<<palette->height()<<'\n';require(palette->size()==QSize(174,recent?312:255),"source palette footprint is174x255, with57px for Recent Colors");const auto selectedCell=f.view->visualRect(f.view->currentIndex());require(palette->mapToGlobal(QPoint())==f.view->viewport()->mapToGlobal(selectedCell.bottomLeft()),"keyboard palettes anchor to the selected cell when Home is collapsed");
  auto swatch=[&](const QString& value){for(auto* button:palette->findChildren<QToolButton*>())if(button->property(font?"fontColor":"fillColor").toString()==value)return button;return static_cast<QToolButton*>(nullptr);};auto* first=swatch("#ffffff");auto* second=swatch("#000000");auto* shade=swatch("#f2f2f2");auto* nextShade=swatch("#d9d9d9");auto* standard=swatch("#c00000");require(first&&second&&shade&&nextShade&&standard,"source theme/shade/standard colors remain native selectable buttons");require(first->geometry()==QRect(5,font?64:33,12,12)&&second->x()-first->x()==17,"base swatches are12px at17px horizontal pitch");require(shade->width()==12&&shade->y()==(font?89:58)&&nextShade->y()-shade->y()==13,"source theme shades form the observed contiguous13px rows after the base gap");require(standard->geometry()==QRect(5,font?200:169,12,12),"Standard Colors retains the source grid position");
  auto* more=palette->findChild<QToolButton*>(font?"tutorial.font.moreColors":"tutorial.fill.moreColors");require(more&&more->text()=="More Colors..."&&!more->icon().isNull()&&more->geometry().y()==(recent?281:224)&&more->height()==30,"More Colors source wording, graphical icon and bottom row are retained");if(font){auto* automatic=palette->findChild<QToolButton*>("tutorial.font.automatic");require(automatic&&automatic->y()==2&&automatic->height()==27&&automatic->y()<first->y(),"Automatic is the first source Font row");}else{auto* none=palette->findChild<QToolButton*>("tutorial.fill.noFill");require(none&&none->y()==193&&none->height()==30&&!none->icon().isNull(),"source No Fill graphical row follows Standard Colors");}
  if(recent){bool seen=false;for(auto* label:palette->findChildren<QLabel*>())if(label->text()=="Recent Colors")seen=true;auto* blue=swatch("#0000ff");require(seen&&blue&&blue->geometry()==QRect(5,257,12,12),"source Recent Colors header and blue swatch occupy their57px section");}
  if(const auto base=qEnvironmentVariable("TIGERSHEETS_PALETTE_CAPTURE_BASE");!base.isEmpty()){auto image=f.window.grab();QPainter painter(&image);painter.drawPixmap(palette->mapToGlobal(QPoint())-f.window.mapToGlobal(QPoint()),palette->grab());painter.end();require(image.save(base+QString(font?(recent?"-font-recent.png":"-font.png"):"-fill.png")),"retain composed native palette capture");}
  QTest::keyClick(palette,Qt::Key_Escape);QApplication::processEvents();require((!palette||!palette->isVisible())&&f.window.currentSession().snapshot()==before&&f.view->selectionModel()->selection()==selected,"source palette inspection does not edit content, history or selection");
 }
}
void sourceLabels(){Fixture f;auto* palette=f.open(true);const auto image=palette->grab().toImage();const auto automatic=inkBounds(image,QRect(38,5,97,21)),theme=inkBounds(image,QRect(15,38,110,16)),standard=inkBounds(image,QRect(15,171,120,21));std::cerr<<"Automatic ink "<<automatic.x()<<','<<automatic.y()<<' '<<automatic.width()<<'x'<<automatic.height()<<" Theme "<<theme.x()<<','<<theme.y()<<' '<<theme.width()<<'x'<<theme.height()<<" Standard "<<standard.x()<<','<<standard.y()<<' '<<standard.width()<<'x'<<standard.height()<<'\n';require(automatic.width()>=54&&automatic.width()<=58&&automatic.height()>=8&&automatic.height()<=10&&automatic.top()>=9&&automatic.top()<=11,"Automatic text matches the source55x9px glyph bounds");require(theme.width()>=74&&theme.width()<=78&&theme.height()>=8&&theme.height()<=10&&theme.top()>=41&&theme.top()<=43,"Theme Colors title matches the source76x9px glyph bounds and baseline");require(standard.width()>=83&&standard.width()<=89&&standard.height()>=8&&standard.height()<=10&&standard.top()>=177&&standard.top()<=179,"Standard Colors matches the source86x9px glyph bounds and baseline");QTest::keyClick(palette,Qt::Key_Escape);}
void sourceKeyPaths(){
 Fixture f;const auto original=f.window.currentSession().snapshot();const auto selected=f.view->selectionModel()->selection();QPointer<QWidget> palette=f.open(true);auto* moreTip=palette->findChild<QLabel*>("tutorial.palette.keyTip.M");require(moreTip&&moreTip->isVisible()&&moreTip->text()=="M","Alt1 displays the source More Colors letter badge");const auto image=palette->grab().toImage();int gray=0;for(int y=moreTip->y();y<moreTip->y()+moreTip->height();++y)for(int x=moreTip->x();x<moreTip->x()+moreTip->width();++x)if(image.pixelColor(x,y)==QColor("#5b5b5b"))++gray;require(gray>50,"the More Colors source badge is actually painted dark gray");
 bool opened=false;QTimer::singleShot(0,&f.window,[&]{if(auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget())){opened=dialog->objectName()=="colors.dialog";dialog->reject();}});QTest::keyClick(palette,Qt::Key_M);QApplication::processEvents();require(opened&&(!palette||!palette->isVisible())&&f.window.currentSession().snapshot()==original,"source M opens the real Colors dialog and Cancel preserves the workbook");
 auto* arrow=f.window.findChild<QToolButton*>("tutorial.home.fontColor.menu");exposeHome(f.window,arrow);QTest::mouseClick(arrow,Qt::LeftButton);QApplication::processEvents();palette=f.window.findChild<QWidget*>("tutorial.fontPalette");require(palette&&palette->isVisible(),"pointer can reopen the actual font palette");moreTip=palette->findChild<QLabel*>("tutorial.palette.keyTip.M");require(moreTip&&!moreTip->isVisible(),"pointer-opened palette initially hides access-key badges");QTest::keyClick(palette,Qt::Key_Alt);QApplication::processEvents();require(palette&&palette->isVisible()&&moreTip->isVisible(),"Alt reveals source letter badges without dismissing the pointer palette");QTest::keyClick(palette,Qt::Key_Escape);QApplication::processEvents();require(f.window.currentSession().snapshot()==original&&f.view->selectionModel()->selection()==selected,"badge inspection and Escape preserve selection and history");
 require(f.model->apply(Json::array({{{"type","set_style"},{"sheet",f.model->sheetId().toStdString()},{"row",7},{"col",3},{"style",{{"fill","#d9d9d9"},{"note","keep"}}}},{{"type","set_cell"},{"sheet",f.model->sheetId().toStdString()},{"row",7},{"col",4},{"input","=0.17"},{"style",{{"fill","#112233"},{"italic",true}}}}})),"seed mixed source fills and formula");const auto filled=f.window.currentSession().snapshotView().at("sheets");palette=f.open(false);auto* noFillTip=palette->findChild<QLabel*>("tutorial.palette.keyTip.N");require(noFillTip&&noFillTip->isVisible(),"Alt6 exposes the source No Fill N badge");QTest::keyClick(palette,Qt::Key_N);QApplication::processEvents();require((!palette||!palette->isVisible())&&f.model->cellStyle(6,2).value("fill",std::string()).empty()&&f.model->cellStyle(6,3).value("fill",std::string()).empty(),"source N clears selected fills through the native palette");require(f.model->cellStyle(6,2).at("note")=="keep"&&f.model->raw(6,3)=="=0.17"&&f.model->cellStyle(6,3).at("italic")==true&&f.view->selectionModel()->selection()==selected,"No Fill preserves notes, formulas, other formatting and selection");require(f.window.executeCommand("undo")&&f.window.currentSession().snapshotView().at("sheets")==filled,"source N is one exact native Undo");
}
}
int main(int argc,char** argv){QApplication app(argc,argv);QTemporaryDir state;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());try{const std::string mode=argc>1?argv[1]:"";if(mode=="layout")sourceLayout();else if(mode=="labels")sourceLabels();else if(mode=="keys")sourceKeyPaths();else initialAutomatic();std::cout<<"Source color palette passed\n";}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
